/* Conteneur principal */
.header-container {
  display: flex;
  flex-wrap: wrap; /* Permet aux éléments de passer à la ligne si nécessaire */
  align-items: center; /* Aligne les éléments verticalement au centre */
  background-color: #ffffff; /* Fond blanc */
