.user-image-container {
  flex: 0 0 auto; /* Ne s'étire pas */
  width: 3rem; /* Taille ajustée */
  height: 3rem;
  border-radius: 50%;
  overflow: hidden;
  border: 0.5px solid #e5e7eb;
  display: flex;
  justify-content: center;
  align-items: center;
}

/* Image utilisateur */
.user-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* Avatar utilisateur */
