  width: 3rem;
  height: 3rem;
  border-radius: 50%;
  background-color: #457b9d;
  color: #ffffff;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
}

/* Contenu textuel */
.text-content {
  flex: 1; /* Prend tout l'espace restant */
  display: flex;
  flex-direction: column; /* Affiche le texte en colonne */
  justify-content: center;
  text-align: left; /* Aligne le texte à gauche */
  gap: 0.2rem; /* Réduction de l'espacement entre les lignes */
}

.title {
  font-size: 1rem; /* Taille réduite */
  font-weight: 600; /* Gras */
  color: #1f2937; /* Couleur sombre */
  margin: 0;
}

.subtitle {
  font-size: 0.8rem;
  font-weight: 400;
  color: #6b7280;
  margin: 0;
}

/* Contenu de la date */
.date-content {
  flex: 0 0 auto; /* Ne s'étire pas */
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-left: auto;
}

