script:
// Fonction pour formater les devises
function format_currency_caisse(value) {
  if (!value) value = 0;
  const formatted = parseFloat(value).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return '€ ' + formatted;
}

// Fonction pour récupérer le solde de la caisse
frappe.call({
  method: 'immo.immo.doctype.caisse.caisse.get_solde_avec_date',
  callback: function(r) {
    if (r.message) {
      const solde = r.message.solde || 0;
      const date_maj = r.message.date_derniere_maj || 'Non définie';

      // Déterminer la couleur et le statut selon le solde
      let color_class, status_text;
      if (solde > 0) {
        color_class = '#16a34a';
        status_text = 'Positif';
      } else if (solde < 0) {
        color_class = '#dc2626';
        status_text = 'Négatif';
      } else {
        color_class = '#6b7280';
        status_text = 'Équilibré';
      }

      // Mettre à jour les éléments
      const statusElement = root_element.querySelector('.caisse-status');
      const amountElement = root_element.querySelector('.caisse-amount');
      const dateElement = root_element.querySelector('.caisse-date');
      const caisseIconElement = root_element.querySelector('.caisse-icon');

      if (statusElement) {
        statusElement.textContent = status_text;
        statusElement.style.color = color_class;
        statusElement.style.fontSize = '0.75rem';
        statusElement.style.fontWeight = '500';
        statusElement.style.padding = '2px 8px';
        statusElement.style.backgroundColor = color_class === '#16a34a' ? '#dcfce7' : color_class === '#dc2626' ? '#fee2e2' : '#f3f4f6';
        statusElement.style.borderRadius = '12px';
        statusElement.style.marginLeft = '8px';
      }

      if (amountElement) {
        amountElement.textContent = format_currency_caisse(solde);
        amountElement.style.color = color_class;
        amountElement.style.fontWeight = '600';
      }

      if (dateElement) {
        const dateText = frappe.datetime.str_to_user(date_maj) || 'Non définie';
        dateElement.textContent = dateText;
      }

      if (caisseIconElement) {
        caisseIconElement.style.color = color_class;
      }
    }
  }
});

