script:
// Vérifie si root_element est disponible (fourni par Frappe pour le conteneur du bloc)
if (root_element) {

  const processCards = (container) => {
    const cards = container.querySelectorAll(".home-card");
    if (cards.length === 0) {
      return false;
    }

    cards.forEach(card => {
      const btn = card.querySelector(".card-actions button[onclick*=\"List\"]");
      if (!btn) return;

      const onclickAttr = btn.getAttribute("onclick");
      const m = onclickAttr.match(/frappe\.set_route\(\s*['"]List['"]\s*,\s*['"]([^'"]+)['"]\s*\)/);
      if (!m || m.length < 2) return;

      const title = card.querySelector(".card-title");
      if (!title) return;

      // Supprimer un badge existant si jamais il y en avait
      const existingBadge = title.querySelector('.badge');
      if (existingBadge) {
        existingBadge.remove();
      }

      // → Aucun appel Frappe ni ajout de span ici, car on veut désactiver les badges
    });

    return true;
  };

  if (!processCards(root_element)) {
    const obs = new MutationObserver((mutations, observer) => {
      if (root_element.querySelectorAll(".home-card").length) {
        if (processCards(root_element)) {
          observer.disconnect();
        }
      }
    });
    obs.observe(root_element, { childList: true, subtree: true });

    setTimeout(() => {
      if (root_element.querySelectorAll(".home-card").length && !root_element.querySelector(".home-card .card-title .badge")) {
        if (processCards(root_element)) {
          obs.disconnect();
        }
      }
    }, 3000);
  }

} else {
  console.error("Erreur Bloc HTML Personnalisé : 'root_element' n'a pas été trouvé.");
}

style:
/* 
  Container principal :
  - 4 colonnes par défaut (grands écrans)
  - 2 colonnes si < 1024px
  - 1 colonne si < 768px
*/
.home-cards-container {
  width: 100%;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
  font-family: "Inter", sans-serif;
}

/* Si vous voulez cibler spécifiquement le deuxième conteneur : */
/* .home-cards-container:nth-of-type(2) {
  grid-template-columns: repeat(4, 1fr);
} */

/* Force chaque carte à remplir sa colonne */
.home-cards-container .home-card {
  width: 100%;
  box-sizing: border-box;
}

/* Carte individuelle */
.home-card {
  border: 1px solid var(--gray-200, #e5e7eb);
  border-radius: 0.5rem;
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0.5rem 1rem;
  background-color: #fff;
}

/* Titre */
.card-title {
  font-size: 0.7rem;
  font-weight: 500;
  margin: 0;
}

/* Cercle (pour l'icône) */
.icon-circle {
  width: 1.6rem;
  height: 1.6rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 0.5rem;
  color: var(--gray-800, #1f2937);
  font-size: 0.8rem;
}

/* Boutons alignés à droite dans la carte */
.card-actions {
  margin-left: auto;
  display: flex;
  gap: 0.5rem;
}

/* Boutons (même taille que le cercle) */
.action-btn {
  width: 1.6rem;
  height: 1.6rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--gray-200, #e5e7eb);
  border-radius: 0.5rem;
  cursor: pointer;
  color: var(--gray-700, #374151);
  transition: background-color 0.2s;
  font-size: 1rem;
  line-height: 1;
  background: #fff;
}

.action-btn:hover {
  background-color: var(--gray-100, #f3f4f6);
}

/* TABLETTE : < 1024px => 2 colonnes */
@media (max-width: 1024px) {
  .home-cards-container {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* MOBILE : < 768px => 1 colonne */
@media (max-width: 768px) {
  .home-cards-container {
    grid-template-columns: 1fr;
  }
}

.badge {
  display: inline-block;
  padding: 0.2em 0.6em;
  font-size: 0.9em;
  font-weight: 500;
  border-radius: 0.25rem;
  color: #fff;
}
.badge-info    { background-color: #3b82f6; }
.badge-success { background-color: #10b981; }
.badge-warning { background-color: #f59e0b; }
.badge-danger  { background-color: #ef4444; }

.badge-custom-count {
  background-color: #e7f1ff; /* Un bleu très clair, similaire à l'image */
  color: #0a58ca; /* Couleur de texte contrastée (bleu foncé) */
  padding: 0.3em 0.5em; /* Ajustement léger du padding si nécessaire */
  font-weight: 600; /* Rendre le texte un peu plus gras */
  vertical-align: middle; /* Meilleur alignement vertical avec le titre */
}

